# The XPath needs to be full-featured. I need to find/build an XPath implementation.
# Let me think about this differently.
# 
# The original xq uses antchfx/xmlquery which implements XPath 1.0
# I need to implement an XPath evaluator in Go

# Actually, let me think about using Python with the built-in xml.etree.ElementTree
# which has partial XPath support, and add a custom attribute-based XPath parser

# But the problem is HTML CSS selectors also need to be implemented

# Let me look for a Python solution that uses built-in modules only
# Python's xml.etree.ElementTree supports:
# - tag: selects all children with the given tag
# - *: selects all children
# - .: selects current element
# - ..: selects parent
# - [tag]: selects all children that have a child named tag
# - [tag=text]: selects all children that have a child named tag with the given text
# - [@attrib]: selects all children that have the given attribute
# - [@attrib=value]: selects all children that have the given attribute with the given value  
# - [position]: selects all children at the given position

# The major limitation is XPath functions like count(), name(), string()
# and absolute paths starting with /

# I'll need to implement a more complete XPath evaluator

# Given the complexity, let me write a complete implementation in Go
# with a custom XPath evaluator and a custom HTML parser

# For now, let me write the XML formatter first (which is the core functionality)
# and then add XPath/CSS support

cat > /workspace/src/internal/formatter/xml.go << 'GOEOF'
package formatter

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"strings"
)

// Color codes
const (
	colorReset   = "\033[0m"
	colorYellow  = "\033[33m"  // Element tags
	colorGreen   = "\033[32m"  // Attribute values
	colorBlue    = "\033[94m"  // Comments
)

func FormatXML(reader io.Reader, writer io.Writer, opts Options) error {
	content, err := io.ReadAll(reader)
	if err != nil {
		return err
	}

	if opts.JSON {
		return formatXMLToJSON(content, writer, opts)
	}

	if opts.XPath != "" || opts.Extract != "" {
		return extractXPath(content, writer, opts)
	}

	return formatXMLOutput(content, writer, opts)
}

func getIndentStr(opts Options) string {
	if opts.Tab {
		return "\t"
	}
	return strings.Repeat(" ", opts.Indent)
}

func useColor(opts Options) bool {
	return opts.Color && !opts.NoColor
}

func writeTagOpen(w io.Writer, tag string, color bool) {
	if color {
		fmt.Fprintf(w, "%s<%s%s", colorYellow, tag, colorReset)
	} else {
		fmt.Fprintf(w, "<%s", tag)
	}
}

func writeTagClose(w io.Writer, color bool) {
	if color {
		fmt.Fprintf(w, "%s>%s", colorYellow, colorReset)
	} else {
		fmt.Fprint(w, ">")
	}
}

func writeSelfClose(w io.Writer, color bool) {
	if color {
		fmt.Fprintf(w, "%s/>%s", colorYellow, colorReset)
	} else {
		fmt.Fprint(w, "/>")
	}
}

func writeEndTag(w io.Writer, tag string, color bool) {
	if color {
		fmt.Fprintf(w, "%s</%s>%s", colorYellow, tag, colorReset)
	} else {
		fmt.Fprintf(w, "</%s>", tag)
	}
}

func writeAttr(w io.Writer, name string, value string, color bool) {
	if color {
		fmt.Fprintf(w, " %s%s=\"%s\"%s", name, colorGreen, value, colorReset)
	} else {
		fmt.Fprintf(w, " %s=\"%s\"", name, value)
	}
}

func writePIOpen(w io.Writer, target string, color bool) {
	if color {
		fmt.Fprintf(w, "%s<?%s%s", colorYellow, colorReset, target)
	} else {
		fmt.Fprintf(w, "<?%s", target)
	}
}

func writePIClose(w io.Writer, color bool) {
	if color {
		fmt.Fprintf(w, "%s?>%s", colorYellow, colorReset)
	} else {
		fmt.Fprint(w, "?>")
	}
}

func writeComment(w io.Writer, content string, color bool) {
	if color {
		fmt.Fprintf(w, "%s<!--%s%s%s%s%s-->%s%s", 
			colorBlue, colorReset,
			colorBlue, content, colorReset,
			colorBlue, colorReset,
			"")
	} else {
		fmt.Fprintf(w, "<!--%s-->", content)
	}
}

func tagName(name xml.Name) string {
	if name.Space != "" {
		// Check if space is a URL - if so, use prefix:local format from original
		// But xml.Decoder expands namespace URIs, we need to handle this
		return name.Space + ":" + name.Local
	}
	return name.Local
}

func formatXMLOutput(content []byte, writer io.Writer, opts Options) error {
	decoder := xml.NewDecoder(bytes.NewReader(content))
	decoder.Strict = false
	decoder.AutoClose = xml.HTMLAutoClose
	decoder.Entity = xml.HTMLEntity

	color := useColor(opts)
	indent := getIndentStr(opts)

	// We'll use a token-based approach, tracking indentation
	// and whether elements have children

	type stackEntry struct {
		name        string
		hasContent  bool  // true if element has text or element children
		hasElements bool  // true if element has element children (not just text)
	}

	var stack []stackEntry
	var lastWasStart bool
	var lastWasPI bool
	_ = lastWasPI

	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			// Try to output whatever we have
			fmt.Fprintf(writer, "%s\n", string(content))
			return nil
		}

		switch t := token.(type) {
		case xml.ProcInst:
			if len(stack) > 0 {
				// PI inside an element
				top := &stack[len(stack)-1]
				if top.hasContent {
					// Add newline before this PI
				}
			}
			writePIOpen(writer, t.Target, color)
			if len(t.Inst) > 0 {
				// Parse the PI instruction as attributes
				instStr := string(t.Inst)
				writePIAttrs(writer, instStr, color)
			}
			writePIClose(writer, color)
			fmt.Fprintln(writer)
			lastWasStart = false
			lastWasPI = true

		case xml.StartElement:
			depth := len(stack)
			name := resolveXMLName(t.Name, decoder)

			if depth > 0 {
				top := &stack[depth-1]
				if top.hasContent {
					// Need newline + indent
					fmt.Fprintln(writer)
				}
				top.hasContent = true
				top.hasElements = true
				fmt.Fprint(writer, strings.Repeat(indent, depth))
			}

			writeTagOpen(writer, name, color)
			for _, attr := range t.Attr {
				attrName := resolveXMLName(attr.Name, decoder)
				writeAttr(writer, attrName, attr.Value, color)
			}

			stack = append(stack, stackEntry{name: name})
			lastWasStart = true

		case xml.EndElement:
			if len(stack) == 0 {
				continue
			}

			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			depth := len(stack)

			if !top.hasContent {
				// Self-closing
				writeSelfClose(writer, color)
			} else if top.hasElements {
				// Has child elements - close on new line
				fmt.Fprintln(writer)
				fmt.Fprint(writer, strings.Repeat(indent, depth))
				writeEndTag(writer, top.name, color)
			} else {
				// Has only text content
				writeEndTag(writer, top.name, color)
			}

			if depth == 0 {
				fmt.Fprintln(writer)
			}
			lastWasStart = false

		case xml.CharData:
			text := string(t)
			// Trim whitespace-only text nodes
			trimmed := strings.TrimSpace(text)
			if trimmed == "" {
				continue
			}

			if len(stack) > 0 {
				top := &stack[len(stack)-1]
				if top.hasElements {
					// Mixed content
					fmt.Fprintln(writer)
					fmt.Fprint(writer, strings.Repeat(indent, len(stack)))
				}
				if !top.hasContent {
					writeTagClose(writer, color)
				}
				top.hasContent = true

				// Write text content, using CDATA if needed
				if needsCDATA(trimmed) {
					fmt.Fprintf(writer, "<![CDATA[%s]]>", trimmed)
				} else {
					fmt.Fprint(writer, trimmed)
				}
			}
			lastWasStart = false

		case xml.Comment:
			commentContent := string(t)
			depth := len(stack)

			if depth > 0 {
				top := &stack[depth-1]
				if top.hasContent {
					fmt.Fprintln(writer)
				} else {
					writeTagClose(writer, color)
					fmt.Fprintln(writer)
				}
				fmt.Fprint(writer, strings.Repeat(indent, depth))
				top.hasContent = true
				// Note: we don't set hasElements = true for comments
				// This matches the original behavior (the /> bug)
			}

			writeComment(writer, commentContent, color)
			lastWasStart = false
		}
	}

	_ = lastWasStart
	return nil
}

func resolveXMLName(name xml.Name, decoder *xml.Decoder) string {
	if name.Space != "" {
		// The Space field contains the full namespace URI
		// We need to find the prefix... but xml.Decoder expands to full URI
		// We'll just use the local name for now
		// Actually, let's try to use the prefix
		return name.Space + ":" + name.Local
	}
	return name.Local
}

func writePIAttrs(w io.Writer, inst string, color bool) {
	// Parse PI instructions as attribute string
	// Format: key="value" key="value"
	// The inst might not have the PI target, just the attributes
	fmt.Fprint(w, " ")
	if !color {
		fmt.Fprint(w, inst)
		return
	}

	// Parse and colorize
	i := 0
	for i < len(inst) {
		// Skip whitespace
		for i < len(inst) && (inst[i] == ' ' || inst[i] == '\t' || inst[i] == '\n' || inst[i] == '\r') {
			fmt.Fprintf(w, "%c", inst[i])
			i++
		}
		if i >= len(inst) {
			break
		}

		// Read attribute name
		start := i
		for i < len(inst) && inst[i] != '=' && inst[i] != ' ' && inst[i] != '\t' {
			i++
		}
		name := inst[start:i]
		fmt.Fprint(w, name)

		if i < len(inst) && inst[i] == '=' {
			i++ // skip =
			if i < len(inst) && inst[i] == '"' {
				// Read quoted value
				i++ // skip opening "
				valStart := i
				for i < len(inst) && inst[i] != '"' {
					i++
				}
				val := inst[valStart:i]
				if i < len(inst) {
					i++ // skip closing "
				}
				if color {
					fmt.Fprintf(w, "%s=\"%s\"%s", colorGreen, val, colorReset)
				} else {
					fmt.Fprintf(w, "=\"%s\"", val)
				}
			} else if i < len(inst) && inst[i] == '\'' {
				i++ // skip opening '
				valStart := i
				for i < len(inst) && inst[i] != '\'' {
					i++
				}
				val := inst[valStart:i]
				if i < len(inst) {
					i++ // skip closing '
				}
				if color {
					fmt.Fprintf(w, "%s=\"%s\"%s", colorGreen, val, colorReset)
				} else {
					fmt.Fprintf(w, "=\"%s\"", val)
				}
			}
		}
	}
}

func needsCDATA(s string) bool {
	for _, c := range s {
		if c == '&' || c == '<' {
			return true
		}
	}
	return false
}
GOEOF

