# For "<?php echo "hello"; ?>":
# PI.Target = "php"
# PI.Inst = `echo "hello"; ` (might have trailing space)
# The panic happens immediately after "<?php" is output
# So the code outputs "<?php" then tries to parse the inst and panics

# The code probably:
# 1. Outputs "<?target" 
# 2. Then splits inst by " " and processes each token
# 3. For the first token "echo" (no "="), tries to split by "=" and access [1] -> panic

# Actually, I wonder if the inst gets trimmed first
cat > /tmp/test_pi2.go << 'EOF'
package main

import (
    "bytes"
    "encoding/xml"
    "fmt"
    "io"
)

func main() {
    tests := []string{
        `<?foo?><root/>`,
        `<?foo bar=baz?><root/>`,
        `<?xml version="1.0"?><root/>`,
        `<?php echo "hello"; ?><root/>`,
    }
    for _, tc := range tests {
        decoder := xml.NewDecoder(bytes.NewReader([]byte(tc)))
        for {
            tok, err := decoder.Token()
            if err == io.EOF { break }
            if err != nil { break }
            switch t := tok.(type) {
            case xml.ProcInst:
                fmt.Printf("Input: %q\n  PI: Target=%q Inst=%q\n", tc, t.Target, string(t.Inst))
            }
        }
    }
}
EOF
go run /tmp/test_pi2.go

