# No XPath in Go standard library
# I need to implement XPath myself in Go

# Let me write a simple but functional XPath evaluator for the common cases
# The most common XPath patterns used with xq are:
# - //tagname  (descendant-or-self)
# - /root/child  (absolute path)
# - //tag[@attr="val"]  (predicate with attribute)
# - //tag[1]  (positional predicate)
# - /root/user/@status  (attribute step)
# - string(), count(), name(), etc. (functions)

# And CSS selectors:
# - "body > p"  (direct child)
# - "head > script"  (direct child)
# - "#id"  (ID selector)
# - ".class"  (class selector)
# - "tag"  (tag selector)

# Let me write a comprehensive implementation
# I'll write it in Python since Python has:
# 1. xml.etree.ElementTree with basic XPath
# 2. html.parser for HTML
# 3. Can handle the rest with custom code

# Actually, Python's lxml would be perfect but it's not available
# And ElementTree has limited XPath support

# Let me go back to the Go approach and write:
# 1. A proper XML tokenizer-based formatter
# 2. A simple XPath evaluator using a tree-based approach
# 3. An HTML tokenizer (implementing the basics)
# 4. A CSS selector evaluator

# The Go standard library encoding/xml can parse XML into a tree or token stream
# I'll use the token stream for formatting
# and build a tree for XPath evaluation

# Let me start writing the Go code now

cat > /tmp/test_approach.go << 'EOF'
package main

import (
    "bytes"
    "encoding/xml"
    "fmt"
    "io"
    "strings"
)

type Node struct {
    Tag      string
    Attrs    []xml.Attr
    Children []*Node
    Text     string
    Tail     string
    IsComment bool
    CommentText string
    IsPI     bool
    PITarget string
    PIInst   string
    SpacePrefixes map[string]string // URI -> prefix
    PrefixSpaces  map[string]string // prefix -> URI
}

func parseXML(content []byte) (*Node, error) {
    decoder := xml.NewDecoder(bytes.NewReader(content))
    decoder.Strict = false

    root := &Node{Tag: "#document"}
    stack := []*Node{root}
    nsStack := []map[string]string{{"xmlns": "xmlns"}} // URI -> prefix

    _ = nsStack

    for {
        tok, err := decoder.Token()
        if err == io.EOF {
            break
        }
        if err != nil {
            return nil, err
        }

        switch t := tok.(type) {
        case xml.StartElement:
            node := &Node{
                Tag:   t.Name.Local,
                Attrs: t.Attr,
            }
            if t.Name.Space != "" {
                node.Tag = t.Name.Space + ":" + t.Name.Local
            }
            parent := stack[len(stack)-1]
            parent.Children = append(parent.Children, node)
            stack = append(stack, node)

        case xml.EndElement:
            if len(stack) > 1 {
                stack = stack[:len(stack)-1]
            }

        case xml.CharData:
            text := string(t)
            if strings.TrimSpace(text) == "" {
                continue
            }
            parent := stack[len(stack)-1]
            if len(parent.Children) == 0 {
                parent.Text = text
            } else {
                last := parent.Children[len(parent.Children)-1]
                last.Tail = text
            }

        case xml.Comment:
            parent := stack[len(stack)-1]
            node := &Node{IsComment: true, CommentText: string(t)}
            parent.Children = append(parent.Children, node)

        case xml.ProcInst:
            parent := stack[len(stack)-1]
            node := &Node{IsPI: true, PITarget: t.Target, PIInst: string(t.Inst)}
            parent.Children = append(parent.Children, node)
        }
    }

    return root, nil
}

func main() {
    content := []byte(`<?xml version="1.0"?><root><child>text</child></root>`)
    root, err := parseXML(content)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }

    var printNode func(*Node, int)
    printNode = func(n *Node, depth int) {
        indent := strings.Repeat("  ", depth)
        if n.IsComment {
            fmt.Printf("%s<!-- %s -->\n", indent, n.CommentText)
            return
        }
        if n.IsPI {
            fmt.Printf("%s<?%s %s?>\n", indent, n.PITarget, n.PIInst)
            return
        }
        if n.Tag == "#document" {
            for _, c := range n.Children {
                printNode(c, depth)
            }
            return
        }
        hasChildren := len(n.Children) > 0
        if hasChildren || n.Text != "" {
            fmt.Printf("%s<%s>", indent, n.Tag)
            if n.Text != "" {
                fmt.Printf("%s", n.Text)
            }
            if hasChildren {
                fmt.Println()
                for _, c := range n.Children {
                    printNode(c, depth+1)
                }
                fmt.Printf("%s", indent)
            }
            fmt.Printf("</%s>\n", n.Tag)
        } else {
            fmt.Printf("%s<%s/>\n", indent, n.Tag)
        }
    }
    printNode(root, 0)
}
EOF
go run /tmp/test_approach.go

