package formatter

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"strings"
	"unicode"
)

// ANSI color codes
const (
	colorReset  = "\033[0m"
	colorYellow = "\033[33m" // Element tags
	colorGreen  = "\033[32m" // Attribute values
	colorBlue   = "\033[94m" // Comments
)

type xmlElement struct {
	name         string
	pendingClose bool // start tag ">" not yet written
	hasContent   bool // has text content or element children
	hasElements  bool // has element children
}

// NSMap tracks namespace URI -> prefix mappings
type nsMap struct {
	frames []map[string]string // each frame: URI -> prefix
}

func (ns *nsMap) push() {
	ns.frames = append(ns.frames, make(map[string]string))
}

func (ns *nsMap) pop() {
	if len(ns.frames) > 0 {
		ns.frames = ns.frames[:len(ns.frames)-1]
	}
}

func (ns *nsMap) add(prefix, uri string) {
	if len(ns.frames) > 0 {
		ns.frames[len(ns.frames)-1][uri] = prefix
	}
}

func (ns *nsMap) uriToPrefix(uri string) string {
	for i := len(ns.frames) - 1; i >= 0; i-- {
		if prefix, ok := ns.frames[i][uri]; ok {
			return prefix
		}
	}
	return ""
}

func resolveName(name xml.Name, ns *nsMap) string {
	if name.Space == "" {
		return name.Local
	}
	if name.Space == "xmlns" {
		return "xmlns:" + name.Local
	}
	// Try to find a prefix for this URI
	prefix := ns.uriToPrefix(name.Space)
	if prefix != "" {
		if prefix == "" {
			return name.Local
		}
		return prefix + ":" + name.Local
	}
	// Fallback: use URI directly (original behavior)
	return name.Space + ":" + name.Local
}

func isWhitespaceOnly(s string) bool {
	for _, c := range s {
		if !unicode.IsSpace(c) {
			return false
		}
	}
	return true
}

func trimTrailingSpaces(s string) string {
	// Only trim ASCII spaces from the right (not tabs, newlines, etc.)
	return strings.TrimRight(s, " ")
}

func needsCDATA(s string) bool {
	return strings.ContainsAny(s, "&<")
}

// FormatXML formats XML content and writes to writer
func FormatXML(reader io.Reader, writer io.Writer, opts Options) error {
	content, err := io.ReadAll(reader)
	if err != nil {
		return err
	}

	if len(bytes.TrimSpace(content)) == 0 {
		fmt.Fprintln(writer)
		return nil
	}

	if opts.JSON {
		return formatXMLToJSON(content, writer, opts)
	}

	if opts.XPath != "" || opts.Extract != "" {
		return extractXPath(content, writer, opts)
	}

	return formatXMLOutput(content, writer, opts)
}

func formatXMLOutput(content []byte, writer io.Writer, opts Options) error {
	decoder := xml.NewDecoder(bytes.NewReader(content))
	decoder.Strict = false

	indentStr := getIndentStr(opts)
	useCol := opts.Color && !opts.NoColor

	stack := make([]xmlElement, 0)
	ns := &nsMap{}
	lastWasElement := false

	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			// On error, output raw content
			fmt.Fprintf(writer, "%s\n", string(content))
			return nil
		}

		switch t := token.(type) {
		case xml.ProcInst:
			depth := len(stack)
			if depth > 0 {
				// PI inside an element - has the bug where pending ">" is not closed first
				// and the PI is written inside the opening tag
				writePIContent(writer, t.Target, string(t.Inst), useCol)
				fmt.Fprintln(writer)
			} else {
				// Top-level PI
				writePIContent(writer, t.Target, string(t.Inst), useCol)
				fmt.Fprintln(writer)
			}
			lastWasElement = false

		case xml.StartElement:
			depth := len(stack)

			// Push namespace frame and collect xmlns declarations
			ns.push()
			for _, attr := range t.Attr {
				if attr.Name.Space == "xmlns" {
					ns.add(attr.Name.Local, attr.Value)
				} else if attr.Name.Space == "" && attr.Name.Local == "xmlns" {
					ns.add("", attr.Value)
				}
			}

			if depth > 0 {
				parent := &stack[depth-1]
				// Close parent's pending ">"
				if parent.pendingClose {
					writePendingClose(writer, useCol)
					parent.pendingClose = false
				}
				// Write newline + indent before child element
				fmt.Fprintf(writer, "\n%s", strings.Repeat(indentStr, depth))
				parent.hasElements = true
				parent.hasContent = true
			}

			// Write start element tag (without ">" - it's pending)
			tagName := resolveName(t.Name, ns)
			writeStartTagOpen(writer, tagName, useCol)
			for _, attr := range t.Attr {
				attrName := resolveName(attr.Name, ns)
				writeAttr(writer, attrName, attr.Value, useCol)
			}

			stack = append(stack, xmlElement{
				name:         tagName,
				pendingClose: true,
				hasContent:   false,
				hasElements:  false,
			})
			lastWasElement = false

		case xml.EndElement:
			if len(stack) == 0 {
				continue
			}

			elem := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			ns.pop()

			depth := len(stack)

			if elem.pendingClose {
				// No content at all -> self-closing
				writeSelfClose(writer, useCol)
			} else if elem.hasElements && lastWasElement {
				// Has element children, last was element -> new line for closing tag
				fmt.Fprintf(writer, "\n%s", strings.Repeat(indentStr, depth))
				writeEndTag(writer, elem.name, useCol)
			} else if elem.hasContent {
				// Only text content (or element children followed by text)
				writeEndTag(writer, elem.name, useCol)
			} else {
				// Wrote ">" (from comment processing) but no text/element content
				// This is the bug: write "/>" instead of "</name>"
				writeSelfClose(writer, useCol)
			}

			lastWasElement = true

		case xml.CharData:
			text := string(t)
			if isWhitespaceOnly(text) {
				continue
			}
			trimmed := trimTrailingSpaces(text)

			if len(stack) > 0 {
				parent := &stack[len(stack)-1]
				if parent.pendingClose {
					writePendingClose(writer, useCol)
					parent.pendingClose = false
				}
				parent.hasContent = true
			}

			if needsCDATA(trimmed) {
				fmt.Fprintf(writer, "<![CDATA[%s]]>", trimmed)
			} else {
				fmt.Fprint(writer, trimmed)
			}
			lastWasElement = false

		case xml.Comment:
			depth := len(stack)
			commentText := string(t)

			if depth > 0 {
				parent := &stack[depth-1]
				if parent.pendingClose {
					writePendingClose(writer, useCol)
					parent.pendingClose = false
				}
				fmt.Fprintf(writer, "\n%s", strings.Repeat(indentStr, depth))
				// NOTE: do NOT set parent.hasContent (this matches the original behavior)
			}

			writeComment(writer, commentText, useCol)
			lastWasElement = false
		}
	}

	// Goroutine-level final newline
	fmt.Fprintln(writer)
	return nil
}

func getIndentStr(opts Options) string {
	if opts.Tab {
		return "\t"
	}
	return strings.Repeat(" ", opts.Indent)
}

func writePendingClose(w io.Writer, color bool) {
	if color {
		fmt.Fprintf(w, "%s>%s", colorYellow, colorReset)
	} else {
		fmt.Fprint(w, ">")
	}
}

func writeStartTagOpen(w io.Writer, tag string, color bool) {
	if color {
		fmt.Fprintf(w, "%s<%s%s", colorYellow, tag, colorReset)
	} else {
		fmt.Fprintf(w, "<%s", tag)
	}
}

func writeSelfClose(w io.Writer, color bool) {
	if color {
		fmt.Fprintf(w, "%s/>%s", colorYellow, colorReset)
	} else {
		fmt.Fprint(w, "/>")
	}
}

func writeEndTag(w io.Writer, tag string, color bool) {
	if color {
		fmt.Fprintf(w, "%s</%s>%s", colorYellow, tag, colorReset)
	} else {
		fmt.Fprintf(w, "</%s>", tag)
	}
}

func writeAttr(w io.Writer, name string, value string, color bool) {
	if color {
		fmt.Fprintf(w, " %s%s=\"%s\"%s", name, colorGreen, value, colorReset)
	} else {
		fmt.Fprintf(w, " %s=\"%s\"", name, value)
	}
}

func writeComment(w io.Writer, content string, color bool) {
	if color {
		fmt.Fprintf(w, "%s<!--%s%s%s%s%s-->%s",
			colorBlue, colorReset,
			colorBlue, content, colorReset,
			colorBlue, colorReset)
	} else {
		fmt.Fprintf(w, "<!--%s-->", content)
	}
}

func writePIContent(w io.Writer, target string, inst string, color bool) {
	if color {
		fmt.Fprintf(w, "%s<?%s%s%s", colorYellow, colorReset, target, "")
	} else {
		fmt.Fprintf(w, "<?%s", target)
	}

	if inst == "" {
		// Empty inst causes panic in original (index out of range)
		// Reproduce the panic by accessing an out-of-bounds index
		parts := strings.Split(inst, " ")
		_ = parts[1] // This will panic
	}

	// Parse PI instruction as space-separated key=value pairs
	tokens := strings.Split(inst, " ")
	for _, tok := range tokens {
		if tok == "" {
			continue
		}
		parts := strings.Split(tok, "=")
		// Original code accesses parts[1] without checking length -> panic if no "="
		key := parts[0]
		val := parts[1] // PANIC if no "="
		if color {
			fmt.Fprintf(w, " %s%s=\"%s\"%s", key, colorGreen, strings.Trim(val, "\""), colorReset)
		} else {
			fmt.Fprintf(w, " %s=%s", key, val)
		}
		_ = val
	}

	if color {
		fmt.Fprintf(w, "%s?>%s", colorYellow, colorReset)
	} else {
		fmt.Fprint(w, "?>")
	}
}
