			for i, c := range children {
				arr[i] = nodeToJSON(c, depth+1, maxDepth)
			}
			result[name] = arr
		}
	}

	return result
}

func getTextContent(node *xmlNode) string {
	if node.Text != "" {
		return node.Text
	}
	var sb strings.Builder
	for _, child := range node.Children {
		sb.WriteString(getTextContent(child))
	}
	return sb.String()
}

func formatXMLToJSON(content []byte, writer io.Writer, opts Options) error {
	decoder := xml.NewDecoder(bytes.NewReader(content))
	decoder.Strict = false

	root, err := buildXMLTree(decoder)
	if err != nil {
		return fmt.Errorf("Error: %v", err)
	}

	// Build the JSON object
	result := make(map[string]interface{})
	for _, child := range root.Children {
		result[child.Name] = nodeToJSON(child, 0, opts.Depth)
	}

	var jsonBytes []byte
	if opts.Compact {
		jsonBytes, err = marshalJSONCompact(result)
	} else {
		jsonBytes, err = marshalJSONIndented(result, "  ")
	}
	if err != nil {
		return fmt.Errorf("Error: %v", err)
	}

	fmt.Fprintf(writer, "%s\n", string(jsonBytes))
	return nil
}

// Custom JSON marshaling to preserve order and format
func marshalJSONIndented(v interface{}, indent string) ([]byte, error) {
	var buf bytes.Buffer
	err := marshalJSONValue(&buf, v, indent, indent)
	return buf.Bytes(), err
}

func marshalJSONCompact(v interface{}) ([]byte, error) {
	return json.Marshal(v)
}

func marshalJSONValue(buf *bytes.Buffer, v interface{}, indent string, currentIndent string) error {
	switch val := v.(type) {
	case string:
		b, err := json.Marshal(val)
		if err != nil {
			return err
		}
		buf.Write(b)
	case nil:
		buf.WriteString("null")
	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case map[string]interface{}:
		return marshalJSONObject(buf, val, indent, currentIndent)
	case []interface{}:
		return marshalJSONArray(buf, val, indent, currentIndent)
	default:
		b, err := json.Marshal(v)
		if err != nil {
			return err
		}
		buf.Write(b)
	}
	return nil
}

func marshalJSONObject(buf *bytes.Buffer, m map[string]interface{}, indent string, currentIndent string) error {
	buf.WriteString("{\n")

	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for i, k := range keys {
		buf.WriteString(currentIndent + indent)
		kb, err := json.Marshal(k)
		if err != nil {
			return err
		}
		buf.Write(kb)
		buf.WriteString(": ")
		if err := marshalJSONValue(buf, m[k], indent, currentIndent+indent); err != nil {
			return err
		}
		if i < len(keys)-1 {
			buf.WriteString(",")
		}
		buf.WriteString("\n")
	}
	buf.WriteString(currentIndent + "}")
	return nil
}

func marshalJSONArray(buf *bytes.Buffer, arr []interface{}, indent string, currentIndent string) error {
	buf.WriteString("[\n")
	for i, item := range arr {
		buf.WriteString(currentIndent + indent)
		if err := marshalJSONValue(buf, item, indent, currentIndent+indent); err != nil {
			return err
		}
		if i < len(arr)-1 {
			buf.WriteString(",")
		}
		buf.WriteString("\n")
	}
	buf.WriteString(currentIndent + "]")
	return nil
}
