package formatter

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"strings"
)

// Simple XPath node representation
type XPathNode struct {
	Name     string
	Attrs    map[string]string
	Children []*XPathNode
	Text     string
	Parent   *XPathNode
	ns       *nsMap
}

func buildXPathTree(content []byte) (*XPathNode, error) {
	decoder := xml.NewDecoder(bytes.NewReader(content))
	decoder.Strict = false

	root := &XPathNode{Name: "#document"}
	stack := []*XPathNode{root}
	ns := newNSMap()

	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}

		switch t := token.(type) {
		case xml.StartElement:
			ns.push()
			node := &XPathNode{
				Name:   resolveName(t.Name, ns),
				Attrs:  make(map[string]string),
				Parent: stack[len(stack)-1],
				ns:     ns,
			}
			for _, attr := range t.Attr {
				if attr.Name.Space == "xmlns" {
					ns.add(attr.Name.Local, attr.Value)
				} else if attr.Name.Space == "" && attr.Name.Local == "xmlns" {
					ns.add("", attr.Value)
				}
				attrName := resolveName(attr.Name, ns)
				node.Attrs[attrName] = attr.Value
			}
			parent := stack[len(stack)-1]
			parent.Children = append(parent.Children, node)
			stack = append(stack, node)

		case xml.EndElement:
			if len(stack) > 1 {
				stack = stack[:len(stack)-1]
				ns.pop()
			}

		case xml.CharData:
			text := string(t)
			if isWhitespaceOnly(text) {
				continue
			}
			text = strings.TrimSpace(text)
			parent := stack[len(stack)-1]
			parent.Text = parent.Text + text
		}
	}

	return root, nil
}

func extractXPath(content []byte, writer io.Writer, opts Options) error {
	xpathExpr := opts.XPath
	if xpathExpr == "" {
		xpathExpr = opts.Extract
	}

	root, err := buildXPathTree(content)
	if err != nil {
		return fmt.Errorf("Error: unable to parse the XPath query")
	}

	results, err := evaluateXPath(root, xpathExpr)
	if err != nil {
		return fmt.Errorf("Error: unable to parse the XPath query")
	}

	limit := -1
	if opts.Extract != "" {
		limit = 1
	}

	count := 0
	for _, node := range results {
		if limit >= 0 && count >= limit {
			break
		}
		if opts.Node {
			// Return XML representation of node
			writeNodeXML(writer, node, opts)
		} else {
			// Return text content
			fmt.Fprintln(writer, getNodeText(node))
		}
		count++
	}

	return nil
}

func getNodeText(node *XPathNode) string {
	if node == nil {
		return ""
	}
	var sb strings.Builder
	sb.WriteString(node.Text)
	for _, child := range node.Children {
		sb.WriteString(getNodeText(child))
	}
	return sb.String()
}

func writeNodeXML(writer io.Writer, node *XPathNode, opts Options) {
	// Write XML representation of node
	indentStr := getIndentStr(opts)
	useCol := opts.Color && !opts.NoColor

	var writeNode func(*XPathNode, int)
	writeNode = func(n *XPathNode, depth int) {
		if n.Name == "#document" {
			for _, child := range n.Children {
				writeNode(child, 0)
			}
			return
		}

		indent := strings.Repeat(indentStr, depth)

		writeStartTagOpen(writer, n.Name, useCol)
		for name, val := range n.Attrs {
			writeAttrPair(writer, name, val, useCol)
		}

		hasChildren := len(n.Children) > 0

		if !hasChildren && n.Text == "" {
			writeSelfClose(writer, useCol)
			fmt.Fprintln(writer)
		} else if !hasChildren {
			writePendingClose(writer, useCol)
			if needsCDATA(n.Text) {
				fmt.Fprintf(writer, "<![CDATA[%s]]>", n.Text)
			} else {
				fmt.Fprint(writer, n.Text)
			}
			writeEndTag(writer, n.Name, useCol)
			fmt.Fprintln(writer)
		} else {
			writePendingClose(writer, useCol)
			if n.Text != "" {
				fmt.Fprint(writer, n.Text)
			}
			fmt.Fprintln(writer)
			for _, child := range n.Children {
				fmt.Fprint(writer, indent+indentStr)
				writeNode(child, depth+1)
			}
			fmt.Fprintf(writer, "%s", indent)
			writeEndTag(writer, n.Name, useCol)
			fmt.Fprintln(writer)
		}
	}

	writeNode(node, 0)
}

// Evaluate an XPath expression against a document root node
func evaluateXPath(root *XPathNode, expr string) ([]*XPathNode, error) {
	// Parse and evaluate the XPath expression
	return evaluateXPathExpr(root, expr, root.Children)
}

func evaluateXPathExpr(root *XPathNode, expr string, contextNodes []*XPathNode) ([]*XPathNode, error) {
	expr = strings.TrimSpace(expr)

	// Handle string() function
	if strings.HasPrefix(expr, "string(") {
		inner := expr[7:len(expr)-1]
		nodes, err := evaluateXPathExpr(root, inner, contextNodes)
		if err != nil {
			return nil, err
		}
		if len(nodes) > 0 {
			text := getNodeText(nodes[0])
			return []*XPathNode{{Name: "#text", Text: text}}, nil
		}
		return []*XPathNode{{Name: "#text", Text: ""}}, nil
	}

	// Handle count() function
	if strings.HasPrefix(expr, "count(") {
		inner := expr[6:len(expr)-1]
		nodes, err := evaluateXPathExpr(root, inner, contextNodes)
		if err != nil {
			return nil, err
		}
		count := fmt.Sprintf("%d", len(nodes))
		return []*XPathNode{{Name: "#text", Text: count}}, nil
	}

	// Handle name() function
	if strings.HasPrefix(expr, "name(") {
		inner := expr[5:len(expr)-1]
		var nodes []*XPathNode
		var err error
		if inner == "" {
			nodes = contextNodes
		} else {
