        if nodes:
            return XPathValue(string_val=nodes[0].name)
        return XPathValue(string_val="")

    # Absolute paths
    if expr.startswith("//"):
        return XPathValue(nodes=_eval_descendant_path(root, context, expr[2:]))

    if expr.startswith("/"):
        # Find the root element
        path = expr[1:]
        step, rest = _split_first_step(path)
        matching = [c for c in root.children if _matches_step(c, step)]
        if not rest:
            return XPathValue(nodes=matching)
        return XPathValue(nodes=_eval_relative_path(root, matching, rest))

    # Relative paths
    return XPathValue(nodes=_eval_relative_path(root, context, expr))


def _eval_descendant_path(root, context, path):
    """Evaluate //path"""
    step, rest = _split_first_step(path)

    # Attribute step
    if step.startswith("@"):
        attr_name = step[1:]
        results = []
        _collect_descendants(root, lambda n: True, lambda n: _get_attr_node(n, attr_name, results))
        return results

    # Check for position predicate
    tag_name, predicate = _parse_step(step)

    # Collect all descendants matching the tag
    all_descendants = []
    _collect_all_descendants(root, all_descendants)

    # Filter by tag name first, then apply predicate
    matching = [n for n in all_descendants if _matches_tag(n, tag_name)]

    if predicate:
        matching = _apply_predicate(matching, predicate)

    if not rest:
        return matching

    # Handle // in the middle of a path
    if rest.startswith("/"):
        return _eval_relative_path(root, matching, rest[1:])

    return _eval_relative_path(root, matching, rest)


def _eval_relative_path(root, context, path):
    """Evaluate a relative path from context nodes"""
    if not path:
        return context

    # Handle // in the path
    if path.startswith("//"):
        return _eval_descendant_path(root, context, path[2:])

    step, rest = _split_first_step(path)

    # Attribute step
    if step.startswith("@"):
        attr_name = step[1:]
        results = []
        for node in context:
            if attr_name in node.attrs:
                attr_node = XMLTreeNode("#attr", parent=node)
                attr_node.text = node.attrs[attr_name]
                results.append(attr_node)
            else:
                # Try local name
                for k, v in node.attrs.items():
                    local_k = k.split(":")[-1] if ":" in k else k
                    if local_k == attr_name:
                        attr_node = XMLTreeNode("#attr", parent=node)
                        attr_node.text = v
                        results.append(attr_node)
                        break
        return results

    tag_name, predicate = _parse_step(step)

    # Get matching children
    matching = []
    for node in context:
        children = [c for c in node.children if _matches_tag(c, tag_name)]
        if predicate:
            children = _apply_predicate(children, predicate)
        matching.extend(children)

    if not rest:
        return matching

    return _eval_relative_path(root, matching, rest)


def _matches_tag(node, tag_name):
    if tag_name == "*":
        return True
    if tag_name == node.name:
        return True
    # Try local name
    local = node.name.split(":")[-1] if ":" in node.name else node.name
    return local == tag_name


def _parse_step(step):
    """Parse an XPath step into (tagname, predicate)"""
    bracket_idx = step.find("[")
    if bracket_idx < 0:
        return step, None
    tag_name = step[:bracket_idx]
    predicate = step[bracket_idx+1:-1]  # Remove [ and ]
    return tag_name, predicate


def _apply_predicate(nodes, predicate):
    """Apply a predicate to a list of nodes"""
    predicate = predicate.strip()

    # Position predicate [N]
    if predicate.isdigit():
        pos = int(predicate)
        return [n for i, n in enumerate(nodes) if i + 1 == pos]

    if predicate == "last()":
        return [nodes[-1]] if nodes else []

    # Attribute predicate
    if predicate.startswith("@"):
        rest = predicate[1:]
        eq_idx = rest.find("=")
        if eq_idx < 0:
            # [@attr] - has attribute
            attr_name = rest
            return [n for n in nodes if attr_name in n.attrs or
                    any(k.split(":")[-1] == attr_name for k in n.attrs)]
        else:
            attr_name = rest[:eq_idx].strip()
            attr_val = rest[eq_idx+1:].strip().strip('"\'')
            result = []
            for n in nodes:
                if attr_name in n.attrs and n.attrs[attr_name] == attr_val:
                    result.append(n)
                    continue
                # Try local name
                for k, v in n.attrs.items():
                    local_k = k.split(":")[-1] if ":" in k else k
                    if local_k == attr_name and v == attr_val:
                        result.append(n)
                        break
            return result

    # Child element predicate
    if "=" not in predicate:
        return [n for n in nodes if any(
            c.name == predicate or c.name.split(":")[-1] == predicate
            for c in n.children
        )]

    return nodes


def _collect_all_descendants(node, result):
    """Collect all descendants of a node"""
    for child in node.children:
        result.append(child)
        _collect_all_descendants(child, result)


def _collect_descendants(root, filter_fn, action_fn):
    """Traverse and collect descendants"""
    for child in root.children:
        if filter_fn(child):
            action_fn(child)
        _collect_descendants(child, filter_fn, action_fn)


def _get_attr_node(node, attr_name, results):
    """Get attribute node if exists"""
    if attr_name in node.attrs:
        attr_node = XMLTreeNode("#attr", parent=node)
        attr_node.text = node.attrs[attr_name]
        results.append(attr_node)
    else:
        for k, v in node.attrs.items():
            local_k = k.split(":")[-1] if ":" in k else k
            if local_k == attr_name:
                attr_node = XMLTreeNode("#attr", parent=node)
                attr_node.text = v
                results.append(attr_node)
                break


def _split_first_step(path):
    """Split an XPath path into the first step and the rest"""
    depth = 0
    i = 0
    while i < len(path):
        c = path[i]
        if c == '[':
            depth += 1
        elif c == ']':
            depth -= 1
        elif c == '/' and depth == 0:
            return path[:i], path[i+1:]
        i += 1
    return path, ""


def _matches_step(node, step):
    """Check if node matches a step (with possible predicate)"""
    tag_name, predicate = _parse_step(step)
    if not _matches_tag(node, tag_name):
        return False
    if predicate:
        return len(_apply_predicate([node], predicate)) > 0
    return True


def extract_xpath(content, opts):
    """Extract content using XPath"""
    try:
        root = build_xml_tree(content)
    except ValueError as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)

    expr = opts.xpath or opts.extract

    try:
        result = evaluate_xpath(root, expr)
    except ValueError as e:
        sys.stderr.write(f"Error: unable to parse the XPath query\n")
        sys.exit(1)

    nodes = result.to_nodes()

    limit = 1 if opts.extract else -1

    for i, node in enumerate(nodes):
        if limit >= 0 and i >= limit:
            break

        if isinstance(node.text, str) and node.name in ("#attr", "#text"):
            # Attribute or text value
            sys.stdout.write(node.text + "\n")
        elif opts.node:
            # Return XML representation
            write_xml_node(sys.stdout, node, 0, opts)
        else:
            # Return text content
            text = node.get_text()
            if text:
                sys.stdout.write(text + "\n")


def write_xml_node(out, node, depth, opts):
    """Write XML representation of a node"""
    indent_str = "\t" if opts.tab else " " * opts.indent
    color = opts.color and not opts.no_color

    def w_start(tag):
        if color:
            out.write(f"{YELLOW}<{tag}{RESET}")
        else:
            out.write(f"<{tag}")

    def w_attr(name, val):
        if color:
            out.write(f' {name}{GREEN}="{val}"{RESET}')
        else:
            out.write(f' {name}="{val}"')

    def w_close():
        if color:
            out.write(f"{YELLOW}>{RESET}")
        else:
            out.write(">")

    def w_self():
        if color:
            out.write(f"{YELLOW}/>{RESET}")
        else:
            out.write("/>")

    def w_end(tag):
        if color:
            out.write(f"{YELLOW}</{tag}>{RESET}")
        else:
            out.write(f"</{tag}>")

    indent = indent_str * depth
    w_start(node.name)
    for k, v in node.attrs.items():
        w_attr(k, v)

    if not node.children and not node.text:
        w_self()
        out.write("\n")
    elif not node.children:
        w_close()
        if needs_cdata(node.text):
            out.write(f"<![CDATA[{node.text}]]>")
        else:
            out.write(node.text)
        w_end(node.name)
        out.write("\n")
    else:
        w_close()
        if node.text:
            out.write(node.text)
        out.write("\n")
        for child in node.children:
            out.write(indent + indent_str)
            write_xml_node(out, child, depth + 1, opts)
        out.write(indent)
        w_end(node.name)
        out.write("\n")


# ============================================================
# XML to JSON Converter
# ============================================================

def build_xml_tree_for_json(content):
    """Build XML tree for JSON conversion"""
    ns_stack = [{}]

    def get_prefix(uri):
        for frame in reversed(ns_stack):
            if uri in frame:
                return frame[uri]
        return None

    def resolve(name):
        if name.startswith("{"):
            uri_end = name.index("}")
            uri = name[1:uri_end]
            local = name[uri_end+1:]
            prefix = get_prefix(uri)
            if prefix is not None:
                return f"{prefix}:{local}" if prefix else local
            return f"{uri}:{local}"
        return name

    def resolve_attr(name):
        """For JSON, use just local name for attrs"""
        if name.startswith("{"):
            uri_end = name.index("}")
            local = name[uri_end+1:]
            return local
        # For xmlns:prefix="uri", return just "prefix"
        if "}" in name:
            return name.split("}")[-1]
        return name

    class Node:
        def __init__(self, name, attrs=None, parent=None):
            self.name = name
            self.attrs = attrs or {}  # name -> value
            self.children = []
            self.text = ""
            self.parent = parent

    root = Node("#document")
    stack = [root]

    def on_start_ns(prefix, uri):
        ns_stack[-1][uri] = prefix if prefix else ""

    def on_end_ns(prefix):
        pass

    def on_start_element(name, attrs_dict):
        ns_stack.append({})
        tag = resolve(name)
        attrs = {}
        for k, v in attrs_dict.items():
            attr_local = resolve_attr(k)
            attrs[attr_local] = v

        parent = stack[-1]
        node = Node(tag, attrs, parent)
        parent.children.append(node)
        stack.append(node)

    def on_end_element(name):
        if len(stack) > 1:
            stack.pop()
        ns_stack.pop()

    def on_char_data(data):
        text = data.strip()
        if not text:
            return
        parent = stack[-1]
        parent.text += text

    p = expat.ParserCreate("}")
    p.StartElementHandler = on_start_element
    p.EndElementHandler = on_end_element
    p.CharacterDataHandler = on_char_data
    p.StartNamespaceDeclHandler = on_start_ns
    p.EndNamespaceDeclHandler = on_end_ns
    p.buffer_text = True
    p.returns_unicode = True

    try:
        if isinstance(content, str):
            p.Parse(content, True)
        else:
            p.Parse(content, True)
    except expat.ExpatError as e:
        raise ValueError(f"Error: invalid character")

    return root


def node_to_json_value(node, depth, max_depth):
    """Convert an XML node to a JSON-compatible value"""
    if max_depth >= 0 and depth >= max_depth:
        return node.get_text() if hasattr(node, 'get_text') else _get_text(node)

    has_attrs = len(node.attrs) > 0
    has_children = len(node.children) > 0
    has_text = bool(node.text)

    # Simple text-only node (no attrs, no children)
    if not has_attrs and not has_children:
        if has_text:
            return node.text
        return {}

    result = {}

    # Add attributes with "@" prefix
    for k, v in sorted(node.attrs.items()):
        result[f"@{k}"] = v

    # Add text as "#text" if there are also attrs or children
    if has_text:
        result["#text"] = node.text

    # Group children by name
    child_groups = {}
    child_order = []
    for child in node.children:
        if child.name not in child_groups:
            child_groups[child.name] = []
            child_order.append(child.name)
        child_groups[child.name].append(child)

    # Sort child names alphabetically
    for name in sorted(child_order):
        children = child_groups[name]
        if len(children) == 1:
            result[name] = node_to_json_value(children[0], depth + 1, max_depth)
        else:
            result[name] = [node_to_json_value(c, depth + 1, max_depth) for c in children]

    return result


def _get_text(node):
    """Get text content of a node recursively"""
    result = node.text if node.text else ""
    for child in node.children:
        result += _get_text(child)
    return result


# Monkey-patch to add get_text method to the node class from build_xml_tree_for_json
# (We use a module-level function instead)


def format_json_indented(obj, indent="  ", current_indent=""):
    """Custom JSON formatter that produces xq-compatible output"""
    if isinstance(obj, dict):
        if not obj:
            return "{\n\n" + current_indent + "}"

        parts = []
        next_indent = current_indent + indent
        for k in sorted(obj.keys()):
            v = obj[k]
            key_str = json.dumps(k)
            val_str = format_json_indented(v, indent, next_indent)
            parts.append(f"{next_indent}{key_str}: {val_str}")

        return "{\n" + ",\n".join(parts) + "\n" + current_indent + "}"

    elif isinstance(obj, list):
        if not obj:
            return "[\n\n" + current_indent + "]"

        parts = []
        next_indent = current_indent + indent
        for item in obj:
            val_str = format_json_indented(item, indent, next_indent)
            parts.append(f"{next_indent}{val_str}")

        return "[\n" + ",\n".join(parts) + "\n" + current_indent + "]"

    else:
        return json.dumps(obj)


def format_json_compact(obj):
    """Format JSON in compact mode (no newlines, spaces after colons)"""
    # Generate indented first, then strip newlines and leading spaces
    indented = format_json_indented(obj)
    # Remove newlines and their following whitespace
    compact = re.sub(r'\n\s*', '', indented)
    return compact


def xml_to_json(content, opts):
    """Convert XML to JSON"""
    try:
        root = build_xml_tree_for_json(content)
    except ValueError as e:
        sys.stderr.write(f"Error: {str(e).replace('Error: ', '')}\n")
        sys.exit(1)

    result = {}
    for child in root.children:
        val = node_to_json_value(child, 0, opts.depth)
        result[child.name] = val

    if opts.compact:
        output = format_json_compact(result)
    else:
        output = format_json_indented(result)

    sys.stdout.write(output + "\n")


# ============================================================
# HTML Parser and Formatter
# ============================================================

class HTMLNode:
    """Represents an HTML node"""
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = attrs or []  # list of (name, value) tuples
        self.children = []
        self.text = ""  # text before first child
        self.tail = ""  # text after closing tag
        self.parent = parent
        self.is_comment = False
        self.comment_text = ""
        self.is_doctype = False
        self.doctype_data = ""

    @classmethod
    def comment_node(cls, text, parent=None):
        n = cls("#comment", parent=parent)
        n.is_comment = True
        n.comment_text = text
        return n

    @classmethod
    def doctype_node(cls, data, parent=None):
        n = cls("#doctype", parent=parent)
        n.is_doctype = True
        n.doctype_data = data
        return n


# HTML void elements (self-closing)
HTML_VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
}


class XQHTMLParser(HTMLParser):
    """HTML parser that builds a tree"""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = HTMLNode("#document")
        self.stack = [self.root]
        self.last_text = ""

    def _current(self):
        return self.stack[-1]

    def handle_starttag(self, tag, attrs):
        parent = self._current()
        node = HTMLNode(tag, attrs, parent)
        parent.children.append(node)

        if tag not in HTML_VOID_ELEMENTS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        # Pop stack to find the matching open tag
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                break

    def handle_data(self, data):
        if is_whitespace_only(data):
            return
        parent = self._current()
        if not parent.children:
            parent.text += data
        else:
            # Append to the last child's tail
            last = parent.children[-1]
            if not hasattr(last, 'tail'):
                last.tail = ""
            last.tail += data

    def handle_comment(self, data):
        parent = self._current()
        node = HTMLNode.comment_node(data, parent)
        parent.children.append(node)

    def handle_decl(self, decl):
        parent = self._current()
        if decl.lower().startswith("doctype"):
            node = HTMLNode.doctype_node(decl, parent)
            parent.children.append(node)

    def handle_entityref(self, name):
        # Decode entity reference
        try:
            import html
            data = html.unescape(f"&{name};")
        except Exception:
            data = f"&{name};"
        self.handle_data(data)

    def handle_charref(self, name):
        try:
            import html
            data = html.unescape(f"&#{name};")
        except Exception:
            data = f"&#{name};"
        self.handle_data(data)


def parse_html(content):
    """Parse HTML content and return root node"""
    parser = XQHTMLParser()
    try:
        parser.feed(content)
        parser.close()
    except Exception:
        pass
    return parser.root


def format_html_output(out, root, opts):
    """Format HTML tree output"""
    indent_str = "\t" if opts.tab else " " * opts.indent
    color = opts.color and not opts.no_color

    def write_tag_open(tag):
        if color:
            out.write(f"{YELLOW}<{tag}{RESET}")
        else:
            out.write(f"<{tag}")

    def write_tag_close():
        if color:
            out.write(f"{YELLOW}>{RESET}")
        else:
            out.write(">")

    def write_self_close():
        if color:
            out.write(f"{YELLOW}/>{RESET}")
        else:
            out.write("/>")

    def write_end_tag(tag):
        if color:
            out.write(f"{YELLOW}</{tag}>{RESET}")
        else:
            out.write(f"</{tag}>")

    def write_attr(name, value):
        if color:
            if value is not None:
                out.write(f' {name}{GREEN}="{value}"{RESET}')
            else:
                out.write(f' {name}')
        else:
            if value is not None:
                out.write(f' {name}="{value}"')
            else:
                out.write(f' {name}')

    def write_node(node, depth):
        indent = indent_str * depth

        if node.is_doctype:
            data = node.doctype_data.lower()
            out.write(f"<!{data}>\n")
            return

        if node.is_comment:
            if color:
                out.write(f"{BLUE}<!--{RESET}{BLUE}{node.comment_text}{RESET}{BLUE}-->{RESET}\n")
            else:
                out.write(f"<!--{node.comment_text}-->\n")
            return

        write_tag_open(node.tag)
        for name, value in (node.attrs or []):
            write_attr(name, value)

        is_void = node.tag in HTML_VOID_ELEMENTS

        if is_void:
            write_self_close()
            out.write("\n")
            return

        has_children = bool(node.children)
        has_text = bool(getattr(node, 'text', ''))

        if not has_children and not has_text:
            write_end_tag(node.tag)
            out.write("\n")
        elif not has_children:
            write_tag_close()
            out.write(node.text or "")
            write_end_tag(node.tag)
            out.write("\n")
        else:
            write_tag_close()
            if node.text:
                out.write(node.text)
            out.write("\n")
            for child in node.children:
                out.write(indent + indent_str)
                write_node(child, depth + 1)
                if hasattr(child, 'tail') and child.tail:
                    out.write(child.tail)
            out.write(indent)
            write_end_tag(node.tag)
            out.write("\n")

    for child in root.children:
        write_node(child, 0)

    out.write("\n")


# ============================================================
# CSS Selector
# ============================================================

def query_css(root, selector):
    """Find elements matching a CSS selector"""
    # Parse the selector
    parts = [p.strip() for p in selector.split(",")]
    results = []
    for part in parts:
        results.extend(_match_selector(root, part.strip()))
    return results


def _match_selector(root, selector):
    """Match a single CSS selector"""
    # Parse combinators: > (child), space (descendant)

    # Tokenize the selector
    tokens = _tokenize_css_selector(selector)

    if not tokens:
        return []

    # Evaluate from the root
    results = _eval_css_selector(root, tokens)
    return results


def _tokenize_css_selector(selector):
    """Tokenize a CSS selector into parts and combinators"""
    tokens = []
    current = ""
    i = 0

    while i < len(selector):
        c = selector[i]
        if c == ' ':
            if current:
                tokens.append(("selector", current))
                current = ""
            # Skip extra spaces
            while i < len(selector) - 1 and selector[i+1] == ' ':
                i += 1
            # Check if next is '>'
            if i < len(selector) - 1 and selector[i+1] != '>':
                tokens.append(("descendant", ""))
        elif c == '>':
            if current:
                tokens.append(("selector", current))
                current = ""
            # Skip spaces
            i += 1
            while i < len(selector) and selector[i] == ' ':
                i += 1
            tokens.append(("child", ""))
            continue
        else:
            current += c
        i += 1

    if current:
        tokens.append(("selector", current))

    return tokens


def _eval_css_selector(root, tokens):
    """Evaluate CSS selector tokens"""
    # Get initial context (all descendants for the first selector)
    if not tokens:
        return []

    # All elements in document
    all_elements = []
    _collect_all_html(root, all_elements)

    # Process tokens
    context = all_elements  # Start with all elements
    i = 0
    first_selector = True

    while i < len(tokens):
        ttype, tval = tokens[i]

        if ttype == "selector":
            if first_selector:
                # Filter all elements by this selector
                context = [n for n in all_elements if _matches_css_simple(n, tval)]
                first_selector = False
            else:
                context = [n for n in context if _matches_css_simple(n, tval)]

        elif ttype == "child":
            i += 1
            if i < len(tokens):
                next_ttype, next_tval = tokens[i]
                if next_ttype == "selector":
                    # Get children of current context that match next_tval
                    new_context = []
                    for node in context:
                        new_context.extend(
                            c for c in node.children
                            if _matches_css_simple(c, next_tval)
                        )
                    context = new_context
                    first_selector = False

        elif ttype == "descendant":
            i += 1
            if i < len(tokens):
                next_ttype, next_tval = tokens[i]
                if next_ttype == "selector":
                    new_context = []
                    for node in context:
                        descs = []
                        _collect_all_html(node, descs)
                        new_context.extend(
                            d for d in descs
                            if _matches_css_simple(d, next_tval)
                        )
                    context = new_context
                    first_selector = False

        i += 1

    return context


def _collect_all_html(node, result):
    """Collect all HTML nodes"""
    for child in (node.children or []):
        if not child.is_comment and not child.is_doctype:
            result.append(child)
            _collect_all_html(child, result)


def _matches_css_simple(node, selector):
    """Check if a node matches a simple CSS selector"""
    if node.is_comment or node.is_doctype:
        return False

    # Parse the simple selector
    # Could be: tag, tag.class, tag#id, .class, #id, *

    if selector == "*":
        return True

    # Parse selector parts
    tag = ""
    classes = []
    id_val = ""

    parts = re.split(r'(?=[.#])', selector)
    for part in parts:
        if not part:
            continue
        if part.startswith("."):
            classes.append(part[1:])
        elif part.startswith("#"):
            id_val = part[1:]
        else:
            tag = part

    if tag and node.tag != tag:
        return False

    attrs_dict = {k: v for k, v in (node.attrs or [])}

    if classes:
        node_classes = attrs_dict.get("class", "").split()
        for cls in classes:
            if cls not in node_classes:
                return False

    if id_val:
        if attrs_dict.get("id") != id_val:
            return False

    return True


def query_css_and_output(content, opts, out):
    """Query HTML with CSS selector and output results"""
    root = parse_html(content)

    nodes = query_css(root, opts.query)

    for node in nodes:
        if opts.node:
            # Output HTML of node
            write_html_node_str(out, node, opts)
        elif opts.attr:
            # Get attribute value
            for name, value in (node.attrs or []):
                if name == opts.attr:
                    out.write(value + "\n")
                    break
        else:
            # Get text content
            text = _get_html_text(node)
            out.write(text + "\n")


def _get_html_text(node):
    """Get text content of HTML node"""
    if node.is_comment or node.is_doctype:
        return ""
    result = node.text or ""
    for child in node.children:
        result += _get_html_text(child)
        if hasattr(child, 'tail') and child.tail:
            result += child.tail
    return result


