    """Write HTML node as string"""
    indent_str = "\t" if opts.tab else " " * opts.indent
    color = opts.color and not opts.no_color

    def write_it(n, depth):
        if n.is_comment:
            if color:
                out.write(f"{BLUE}<!--{RESET}{BLUE}{n.comment_text}{RESET}{BLUE}-->{RESET}\n")
            else:
                out.write(f"<!--{n.comment_text}-->\n")
            return

        if color:
            out.write(f"{YELLOW}<{n.tag}{RESET}")
        else:
            out.write(f"<{n.tag}")

        for name, value in (n.attrs or []):
            if color:
                out.write(f' {name}{GREEN}="{value}"{RESET}')
            else:
                out.write(f' {name}="{value}"')

        is_void = n.tag in HTML_VOID_ELEMENTS
        has_children = bool(n.children)
        has_text = bool(n.text)

        if is_void:
            if color:
                out.write(f"{YELLOW}/>{RESET}")
            else:
                out.write("/>")
            out.write("\n")
        elif not has_children and not has_text:
            if color:
                out.write(f"{YELLOW}></{n.tag}>{RESET}")
            else:
                out.write(f"></{n.tag}>")
            out.write("\n")
        elif not has_children:
            if color:
                out.write(f"{YELLOW}>{RESET}{n.text}{YELLOW}</{n.tag}>{RESET}")
            else:
                out.write(f">{n.text}</{n.tag}>")
            out.write("\n")
        else:
            if color:
                out.write(f"{YELLOW}>{RESET}")
            else:
                out.write(">")
            if n.text:
                out.write(n.text)
            out.write("\n")
            for child in n.children:
                out.write(indent_str * (depth + 1))
                write_it(child, depth + 1)
            out.write(indent_str * depth)
            if color:
                out.write(f"{YELLOW}</{n.tag}>{RESET}")
            else:
                out.write(f"</{n.tag}>")
            out.write("\n")

    write_it(node, 0)


# ============================================================
# HTML Formatter
# ============================================================

def format_html(content, out, opts):
    """Format HTML content"""
    root = parse_html(content)
    format_html_output(out, root, opts)


