def evaluate_xpath(root, expr):
    """Evaluate an XPath expression against a document root"""
    try:
        return _eval_xpath(root, root.children, expr.strip())
    except Exception as e:
        raise ValueError(f"unable to parse the XPath query: {e}")


def _eval_xpath(root, context, expr):
    """Evaluate XPath expression"""
    expr = expr.strip()

    # Function calls
    if expr.startswith("string(") and expr.endswith(")"):
        inner = expr[7:-1].strip()
        if inner:
            result = _eval_xpath(root, context, inner)
            if result.nodes:
                return XPathValue(string_val=result.nodes[0].get_text())
            return XPathValue(string_val=result.to_string())
        elif context:
            return XPathValue(string_val=context[0].get_text())
        return XPathValue(string_val="")

