class XMLNode:
    def __init__(self, name, attrs_list=None, parent=None):
        self.name = name  # tag name (with ns prefix)
        self.local_name = name.split(":")[-1] if ":" in name else name
        self.attrs = attrs_list or []  # list of (name, value) tuples
        self.attrs_dict = {}  # name -> value dict for fast lookup
        if attrs_list:
            self.attrs_dict = dict(attrs_list)
