    expr = expr.strip()
    try:
        return _eval_expr(root, root.children, expr)
    except IndexError:
        raise ValueError("unable to parse the XPath query")


def _eval_expr(root, context, expr):
    """Evaluate XPath expression against context"""
    expr = expr.strip()

    # Function calls
    m = re.match(r'^(\w+)\((.*)?\)$', expr)
    if m:
        func_name = m.group(1)
        inner = m.group(2).strip() if m.group(2) else ""

        if func_name == "string":
            if inner:
                nodes = _eval_expr(root, context, inner)
                return [XMLNode("#text", parent=None)] if not nodes else [
                    _text_node(nodes[0].get_text() if hasattr(nodes[0], 'get_text') else nodes[0].text)
