    n.text = text
    n.get_text = lambda: text
    return n


def _eval_descendant(root, path):
    """Evaluate //path from document root"""
    step, rest = _split_step(path)

    # Attribute step
    if step.startswith("@"):
        attr_name = step[1:]
        results = []
        _each_descendant(root, lambda n: _collect_attr(n, attr_name, results))
        return results

    tag, pred = _parse_step(step)

    # Collect all descendants
