    by_tag = [n for n in all_desc if _match_tag(n, tag)]

    # Apply predicate (with positional context)
    if pred:
        by_tag = _apply_pred(by_tag, pred)

    if not rest:
        return by_tag

    if rest.startswith("/"):
        return _eval_relative(root, by_tag, rest[1:])
    return _eval_relative(root, by_tag, rest)


def _eval_relative(root, context, path):
    """Evaluate relative path from context nodes"""
    if not path:
        return list(context)

    if path.startswith("//"):
        return _eval_descendant(root, path[2:])

    step, rest = _split_step(path)

    # Attribute step
    if step.startswith("@"):
        attr_name = step[1:]
        results = []
        for node in context:
            _collect_attr(node, attr_name, results)
        return results

    tag, pred = _parse_step(step)

    # Get children matching tag from all context nodes
    matching = []
    for node in context:
        children = [c for c in node.children if _match_tag(c, tag)]
        if pred:
            children = _apply_pred(children, pred)
        matching.extend(children)

    if not rest:
        return matching

    return _eval_relative(root, matching, rest)


def _collect_attr(node, attr_name, results):
    """Collect an attribute node from the given node"""
    val = node.get_attr(attr_name)
    if val is not None:
        n = XMLNode("#attr")
        n.text = val
        n.get_text = lambda: val
        results.append(n)


def _each_descendant(node, fn):
    """Visit each descendant of node"""
    for child in node.children:
        fn(child)
        _each_descendant(child, fn)


def _match_tag(node, tag):
    if tag == "*":
        return True
    if node.name == tag:
        return True
    local = node.name.split(":")[-1] if ":" in node.name else node.name
    return local == tag


def _parse_step(step):
    """Parse step into (tag, predicate) where predicate may be None"""
    idx = step.find("[")
    if idx < 0:
        return step, None
    return step[:idx], step[idx+1:-1]


def _apply_pred(nodes, pred):
    """Apply predicate to list of nodes, return filtered list"""
    pred = pred.strip()

    # Position predicate
    if pred.isdigit():
        pos = int(pred)
        # Position is relative to each parent group
        # For descendant-or-self queries, we use the current list
        return [nodes[pos-1]] if 0 < pos <= len(nodes) else []

    if pred == "last()":
        return [nodes[-1]] if nodes else []

    # Attribute predicate
    if pred.startswith("@"):
        attr_part = pred[1:]
        eq_idx = attr_part.find("=")
        if eq_idx < 0:
            # [@attr] - has attribute
            attr_name = attr_part
            return [n for n in nodes if n.get_attr(attr_name) is not None]
        else:
            attr_name = attr_part[:eq_idx].strip()
            attr_val = attr_part[eq_idx+1:].strip().strip('"\'')
            return [n for n in nodes if n.get_attr(attr_name) == attr_val]

    # Child element predicate [tag]
    if "=" not in pred:
        return [n for n in nodes if any(
            c.name == pred or (c.name.split(":")[-1] if ":" in c.name else c.name) == pred
            for c in n.children
