class XMLNode:
    def __init__(self, name, attrs_list=None, parent=None):
        self.name = name  # tag name (with ns prefix)
        self.local_name = name.split(":")[-1] if ":" in name else name
        self.attrs = attrs_list or []  # list of (name, value) tuples
        self.attrs_dict = {}  # name -> value dict for fast lookup
        if attrs_list:
            self.attrs_dict = dict(attrs_list)
        self.children = []
        self.text = ""
        self.parent = parent
        self.sibling_index = {}  # {name: position among siblings}

    def get_text(self):
        result = self.text
        for child in self.children:
            result += child.get_text()
        return result

    def get_attr(self, name):
        """Get attribute value, trying both full name and local name"""
        if name in self.attrs_dict:
            return self.attrs_dict[name]
        # Try local name
        for k, v in self.attrs:
            local = k.split(":")[-1] if ":" in k else k
            if local == name:
                return v
        return None


def build_xml_tree(content):
    """Build XML tree from content"""
    root = XMLNode("#document")
    stack = [root]

    def on_start_element(name, attrs_dict):
        attrs_list = []
        if isinstance(attrs_dict, dict):
            attrs_list = list(attrs_dict.items())

        parent = stack[-1]
        node = XMLNode(name, attrs_list, parent)
        parent.children.append(node)

        # Set sibling positions for position predicates
        name_count = {}
        for sibling in parent.children:
            n = sibling.name
            name_count[n] = name_count.get(n, 0) + 1
            sibling.sibling_index[n] = name_count[n]

        stack.append(node)

    def on_end_element(name):
        if len(stack) > 1:
            stack.pop()

    def on_char_data(data):
        text = data.strip()
        if text:
            parent = stack[-1]
            parent.text += text

    p = expat_module.ParserCreate()
    p.StartElementHandler = on_start_element
    p.EndElementHandler = on_end_element
    p.CharacterDataHandler = on_char_data
    p.ordered_attributes = 1
    p.buffer_text = True

    try:
        if isinstance(content, str):
            p.Parse(content.encode('utf-8'), True)
        else:
            p.Parse(content, True)
    except expat_module.ExpatError as e:
        raise ValueError(f"XML parse error: {e}")

    return root


# ============================================================
# XPath Evaluator
# ============================================================

def evaluate_xpath(root, expr):
    """Evaluate XPath expression, return list of nodes or text values"""
    expr = expr.strip()
    try:
        return _eval_expr(root, root.children, expr)
    except IndexError:
        raise ValueError("unable to parse the XPath query")


def _eval_expr(root, context, expr):
    """Evaluate XPath expression against context"""
    expr = expr.strip()

    # Function calls
    m = re.match(r'^(\w+)\((.*)?\)$', expr)
    if m:
        func_name = m.group(1)
        inner = m.group(2).strip() if m.group(2) else ""

        if func_name == "string":
            if inner:
                nodes = _eval_expr(root, context, inner)
                return [XMLNode("#text", parent=None)] if not nodes else [
                    _text_node(nodes[0].get_text() if hasattr(nodes[0], 'get_text') else nodes[0].text)
                ]
            elif context:
                return [_text_node(context[0].get_text())]
            return [_text_node("")]

        elif func_name == "count":
            nodes = _eval_expr(root, context, inner) if inner else context
            return [_text_node(str(len(nodes)))]

        elif func_name == "name":
            if inner:
                nodes = _eval_expr(root, context, inner)
            else:
                nodes = context
            if nodes:
                return [_text_node(nodes[0].name)]
            return [_text_node("")]

    # Absolute paths
    if expr.startswith("//"):
        return _eval_descendant(root, expr[2:])

    if expr.startswith("/"):
        path = expr[1:]
        step, rest = _split_step(path)
        matching = [c for c in root.children if _match_step(c, step)]
        if not rest:
            return matching
        return _eval_relative(root, matching, rest)

    # Relative paths
    return _eval_relative(root, context, expr)


def _text_node(text):
    n = XMLNode("#text")
    n.text = text
    n.get_text = lambda: text
    return n


def _eval_descendant(root, path):
    """Evaluate //path from document root"""
    step, rest = _split_step(path)

    # Attribute step
    if step.startswith("@"):
        attr_name = step[1:]
        results = []
        _each_descendant(root, lambda n: _collect_attr(n, attr_name, results))
        return results

    tag, pred = _parse_step(step)

    # Collect all descendants
    all_desc = []
    _each_descendant(root, all_desc.append)

    # Filter by tag name
    by_tag = [n for n in all_desc if _match_tag(n, tag)]

    # Apply predicate (with positional context)
    if pred:
        by_tag = _apply_pred(by_tag, pred)

    if not rest:
        return by_tag

    if rest.startswith("/"):
        return _eval_relative(root, by_tag, rest[1:])
    return _eval_relative(root, by_tag, rest)


def _eval_relative(root, context, path):
    """Evaluate relative path from context nodes"""
    if not path:
        return list(context)

    if path.startswith("//"):
        return _eval_descendant(root, path[2:])

    step, rest = _split_step(path)

    # Attribute step
    if step.startswith("@"):
        attr_name = step[1:]
        results = []
        for node in context:
            _collect_attr(node, attr_name, results)
        return results

    tag, pred = _parse_step(step)

    # Get children matching tag from all context nodes
    matching = []
    for node in context:
        children = [c for c in node.children if _match_tag(c, tag)]
        if pred:
            children = _apply_pred(children, pred)
        matching.extend(children)

    if not rest:
        return matching

    return _eval_relative(root, matching, rest)


def _collect_attr(node, attr_name, results):
    """Collect an attribute node from the given node"""
    val = node.get_attr(attr_name)
    if val is not None:
        n = XMLNode("#attr")
        n.text = val
        n.get_text = lambda: val
        results.append(n)


def _each_descendant(node, fn):
    """Visit each descendant of node"""
    for child in node.children:
        fn(child)
        _each_descendant(child, fn)


def _match_tag(node, tag):
    if tag == "*":
        return True
    if node.name == tag:
        return True
    local = node.name.split(":")[-1] if ":" in node.name else node.name
    return local == tag


def _parse_step(step):
    """Parse step into (tag, predicate) where predicate may be None"""
    idx = step.find("[")
    if idx < 0:
        return step, None
    return step[:idx], step[idx+1:-1]


def _apply_pred(nodes, pred):
    """Apply predicate to list of nodes, return filtered list"""
    pred = pred.strip()

    # Position predicate
    if pred.isdigit():
        pos = int(pred)
        # Position is relative to each parent group
        # For descendant-or-self queries, we use the current list
        return [nodes[pos-1]] if 0 < pos <= len(nodes) else []

    if pred == "last()":
        return [nodes[-1]] if nodes else []

    # Attribute predicate
    if pred.startswith("@"):
        attr_part = pred[1:]
        eq_idx = attr_part.find("=")
        if eq_idx < 0:
            # [@attr] - has attribute
            attr_name = attr_part
            return [n for n in nodes if n.get_attr(attr_name) is not None]
        else:
            attr_name = attr_part[:eq_idx].strip()
            attr_val = attr_part[eq_idx+1:].strip().strip('"\'')
            return [n for n in nodes if n.get_attr(attr_name) == attr_val]

    # Child element predicate [tag]
    if "=" not in pred:
        return [n for n in nodes if any(
            c.name == pred or (c.name.split(":")[-1] if ":" in c.name else c.name) == pred
            for c in n.children
        )]

    return nodes


def _match_step(node, step):
    """Check if node matches a step"""
    tag, pred = _parse_step(step)
    if not _match_tag(node, tag):
        return False
    if pred:
        return len(_apply_pred([node], pred)) > 0
    return True


def _split_step(path):
    """Split path at first unescaped /"""
    depth = 0
    for i, c in enumerate(path):
        if c == '[':
            depth += 1
        elif c == ']':
            depth -= 1
        elif c == '/' and depth == 0:
            return path[:i], path[i+1:]
    return path, ""


def extract_xpath_nodes(content, opts):
    """Extract nodes using XPath expression"""
    try:
        root = build_xml_tree(content)
    except ValueError as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)

    expr = opts.xpath or opts.extract

    try:
        nodes = evaluate_xpath(root, expr)
    except ValueError as e:
        sys.stderr.write(f"Error: unable to parse the XPath query\n")
        sys.exit(1)

    limit = 1 if opts.extract and not opts.xpath else -1

    color = opts.color and not opts.no_color
    indent_str = "\t" if opts.tab else " " * opts.indent

    for i, node in enumerate(nodes):
        if limit >= 0 and i >= limit:
            break

        if opts.node:
            _write_node_xml(sys.stdout, node, 0, indent_str, color)
        else:
            text = node.get_text() if hasattr(node, 'get_text') else node.text
            sys.stdout.write(text + "\n")


def _write_node_xml(out, node, depth, indent_str, color):
    """Write XML representation of a node"""
    indent = indent_str * depth

    def w_start(tag):
        out.write(f"{YELLOW}<{tag}{RESET}" if color else f"<{tag}")

    def w_attr(name, val):
        out.write(f' {name}{GREEN}="{val}"{RESET}' if color else f' {name}="{val}"')

    def w_close():
        out.write(f"{YELLOW}>{RESET}" if color else ">")

    def w_self():
        out.write(f"{YELLOW}/>{RESET}" if color else "/>")

    def w_end(tag):
        out.write(f"{YELLOW}</{tag}>{RESET}" if color else f"</{tag}>")

    w_start(node.name)
    for name, val in node.attrs:
        w_attr(name, val)

    has_children = bool(node.children)
    has_text = bool(node.text)

    if not has_children and not has_text:
        w_self()
        out.write("\n")
    elif not has_children:
        w_close()
        if needs_cdata(node.text):
            out.write(f"<![CDATA[{node.text}]]>")
        else:
            out.write(node.text)
        w_end(node.name)
        out.write("\n")
    else:
        w_close()
        if has_text:
            out.write(node.text)
        out.write("\n")
        for child in node.children:
            out.write(indent + indent_str)
            _write_node_xml(out, child, depth + 1, indent_str, color)
        out.write(indent)
        w_end(node.name)
        out.write("\n")


# ============================================================
# JSON Converter
# ============================================================

def build_xml_tree_json(content):
    """Build XML tree for JSON conversion (uses local names for attrs)"""
    root = XMLNode("#document")
    stack = [root]

    def on_start_element(name, attrs_dict):
        # For JSON, use just local names for attributes
        attrs_list = []
        if isinstance(attrs_dict, dict):
            for k, v in attrs_dict.items():
                # Strip namespace prefix from attribute names  
                local_k = k.split(":")[-1] if ":" in k else k
                attrs_list.append((local_k, v))

        parent = stack[-1]
        node = XMLNode(name, attrs_list, parent)
        parent.children.append(node)
        stack.append(node)

    def on_end_element(name):
        if len(stack) > 1:
            stack.pop()

    def on_char_data(data):
        text = data.strip()
        if text:
            parent = stack[-1]
            parent.text += text

    p = expat_module.ParserCreate()
    p.StartElementHandler = on_start_element
    p.EndElementHandler = on_end_element
    p.CharacterDataHandler = on_char_data
    p.ordered_attributes = 1
    p.buffer_text = True

    try:
        if isinstance(content, str):
            p.Parse(content.encode('utf-8'), True)
        else:
            p.Parse(content, True)
    except expat_module.ExpatError as e:
        raise ValueError(f"invalid character")

    return root


def node_to_json(node, depth, max_depth):
    """Convert an XML node to a JSON-compatible Python value"""
    if max_depth >= 0 and depth >= max_depth:
        return node.get_text()

    has_attrs = len(node.attrs) > 0
    has_children = len(node.children) > 0
    has_text = bool(node.text)

    if not has_attrs and not has_children:
        if has_text:
            return node.text
        return {}

    result = {}

    for name, val in sorted(node.attrs):
        result[f"@{name}"] = val

    if has_text:
        result["#text"] = node.text

    child_groups = {}
    child_order = []
    for child in node.children:
        if child.name not in child_groups:
            child_groups[child.name] = []
            child_order.append(child.name)
        child_groups[child.name].append(child)

    for name in sorted(child_order):
        children = child_groups[name]
        if len(children) == 1:
            result[name] = node_to_json(children[0], depth + 1, max_depth)
        else:
            result[name] = [node_to_json(c, depth + 1, max_depth) for c in children]

    return result


def format_json_indented(obj, indent="  ", curr=""):
    """Custom JSON formatter matching xq's output format"""
    if isinstance(obj, dict):
        if not obj:
            return "{\n\n" + curr + "}"
        parts = []
        next_curr = curr + indent
        for k in sorted(obj.keys()):
            v = obj[k]
            key_str = json.dumps(k)
            val_str = format_json_indented(v, indent, next_curr)
            parts.append(f"{next_curr}{key_str}: {val_str}")
        return "{\n" + ",\n".join(parts) + "\n" + curr + "}"
    elif isinstance(obj, list):
        if not obj:
            return "[]"
        parts = []
        next_curr = curr + indent
        for item in obj:
            val_str = format_json_indented(item, indent, next_curr)
            parts.append(f"{next_curr}{val_str}")
        return "[\n" + ",\n".join(parts) + "\n" + curr + "]"
    else:
        return json.dumps(obj, ensure_ascii=False)


def format_json_compact(obj):
    """Format JSON compactly (no newlines, space after colon)"""
    indented = format_json_indented(obj)
    return re.sub(r'\n\s*', '', indented)


def xml_to_json(content, opts):
    """Convert XML to JSON and output"""
    try:
        root = build_xml_tree_json(content)
    except ValueError as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)

    result = {}
    for child in root.children:
        result[child.name] = node_to_json(child, 0, opts.depth)

    if opts.compact:
        output = format_json_compact(result)
    else:
        output = format_json_indented(result)

    sys.stdout.write(output + "\n")


# ============================================================
# HTML Parser and Formatter
# ============================================================

from html.parser import HTMLParser

HTML_VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
}


class HTMLNode:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = attrs or []
        self.children = []
        self.text = ""
        self.tail = ""
        self.parent = parent
        self.is_comment = False
        self.comment_text = ""
        self.is_doctype = False
        self.doctype_data = ""

    def get_attr_dict(self):
        return {k: v for k, v in self.attrs if v is not None}


class XQHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = HTMLNode("#document")
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        parent = self.stack[-1]
        node = HTMLNode(tag, attrs, parent)
        parent.children.append(node)
        if tag.lower() not in HTML_VOID_ELEMENTS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag.lower():
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if is_whitespace_only(data):
            return
        parent = self.stack[-1]
        if not parent.children:
            parent.text += data
        else:
            last = parent.children[-1]
            last.tail = (last.tail or "") + data

    def handle_comment(self, data):
        parent = self.stack[-1]
        node = HTMLNode("#comment", parent=parent)
        node.is_comment = True
        node.comment_text = data
        parent.children.append(node)

    def handle_decl(self, decl):
        parent = self.stack[-1]
        if decl.lower().startswith("doctype"):
            node = HTMLNode("#doctype", parent=parent)
            node.is_doctype = True
            node.doctype_data = decl.lower()
            parent.children.append(node)


def parse_html(content):
    parser = XQHTMLParser()
    try:
        parser.feed(content)
        parser.close()
    except Exception:
        pass
    return parser.root


def write_html_node(out, node, depth, indent_str, color):
    """Write formatted HTML node"""
    indent = indent_str * depth

    if node.is_doctype:
        out.write(f"<!{node.doctype_data}>\n")
        return

    if node.is_comment:
        if color:
            out.write(f"{BLUE}<!--{RESET}{BLUE}{node.comment_text}{RESET}{BLUE}-->{RESET}\n")
        else:
            out.write(f"<!--{node.comment_text}-->\n")
        return

    if color:
        out.write(f"{YELLOW}<{node.tag}{RESET}")
    else:
        out.write(f"<{node.tag}")

    for name, value in (node.attrs or []):
        if color:
            if value is not None:
                out.write(f' {name}{GREEN}="{value}"{RESET}')
            else:
                out.write(f' {name}')
        else:
            if value is not None:
                out.write(f' {name}="{value}"')
            else:
                out.write(f' {name}')

    is_void = node.tag.lower() in HTML_VOID_ELEMENTS
    has_children = bool(node.children)
    has_text = bool(node.text)

    if is_void:
        if color:
            out.write(f"{YELLOW}/>{RESET}")
        else:
            out.write("/>")
        out.write("\n")
        return

    if not has_children and not has_text:
        if color:
            out.write(f"{YELLOW}></{node.tag}>{RESET}")
        else:
            out.write(f"></{node.tag}>")
        out.write("\n")
    elif not has_children:
        if color:
            out.write(f"{YELLOW}>{RESET}{node.text}{YELLOW}</{node.tag}>{RESET}")
        else:
            out.write(f">{node.text}</{node.tag}>")
        out.write("\n")
    else:
        if color:
            out.write(f"{YELLOW}>{RESET}")
        else:
            out.write(">")
        if node.text:
            out.write(node.text)
        out.write("\n")
        for child in node.children:
            out.write(indent + indent_str)
            write_html_node(out, child, depth + 1, indent_str, color)
            if hasattr(child, 'tail') and child.tail:
                # Write tail text inline after closing tag would cause issues
                pass
        out.write(indent)
        if color:
            out.write(f"{YELLOW}</{node.tag}>{RESET}")
        else:
            out.write(f"</{node.tag}>")
        out.write("\n")


def format_html(content, out, opts):
    """Format HTML content"""
    indent_str = "\t" if opts.tab else " " * opts.indent
    color = opts.color and not opts.no_color
    root = parse_html(content)
    for child in root.children:
        write_html_node(out, child, 0, indent_str, color)
    out.write("\n")


# ============================================================
# CSS Selector
# ============================================================

def _collect_html_elements(node, result):
    """Collect all element nodes (not comments/doctype)"""
    for child in node.children:
        if not child.is_comment and not child.is_doctype:
            result.append(child)
            _collect_html_elements(child, result)


def _match_simple_selector(node, selector):
    """Check if node matches a simple CSS selector"""
    if node.is_comment or node.is_doctype:
        return False
    if selector == "*":
        return True

    # Parse the selector
    tag = ""
    classes = []
    id_val = ""

    # Split by . and #
    pos = 0
    current = ""
    mode = "tag"

    for c in selector:
        if c == '.':
            if mode == "tag":
                tag = current
            elif mode == "class":
                classes.append(current)
            elif mode == "id":
                id_val = current
            current = ""
            mode = "class"
        elif c == '#':
            if mode == "tag":
                tag = current
            elif mode == "class":
                classes.append(current)
            elif mode == "id":
                id_val = current
            current = ""
            mode = "id"
        else:
            current += c

    if mode == "tag":
        tag = current
    elif mode == "class":
        classes.append(current)
    elif mode == "id":
        id_val = current

    if tag and node.tag != tag:
        return False

    attrs_dict = {k: v for k, v in (node.attrs or []) if v is not None}

    if classes:
        node_classes = attrs_dict.get("class", "").split()
        for cls in classes:
            if cls not in node_classes:
                return False

    if id_val:
        if attrs_dict.get("id") != id_val:
            return False

    return True


def _parse_css_selector(selector):
    """Parse CSS selector into list of (combinator, simple_selector) pairs"""
    tokens = []
    i = 0
    current = ""

    while i < len(selector):
        c = selector[i]
        if c == ' ':
            if current.strip():
                tokens.append(("", current.strip()))
                current = ""
            # Look ahead for > combinator
            j = i + 1
            while j < len(selector) and selector[j] == ' ':
                j += 1
            if j < len(selector) and selector[j] == '>':
                tokens.append((">", ""))
                i = j + 1
                # Skip spaces after >
                while i < len(selector) and selector[i] == ' ':
                    i += 1
                continue
            else:
                tokens.append((" ", ""))
        elif c == '>':
            if current.strip():
                tokens.append(("", current.strip()))
                current = ""
            tokens.append((">", ""))
            i += 1
            while i < len(selector) and selector[i] == ' ':
                i += 1
            continue
        else:
            current += c
        i += 1

    if current.strip():
        tokens.append(("", current.strip()))

    return tokens


def query_css(root, selector):
    """Find HTML elements matching a CSS selector"""
    # Parse selector
    tokens = _parse_css_selector(selector.strip())

    if not tokens:
        return []

    # Get first selector
    first_combinator, first_sel = tokens[0]

    # Get all matching elements for first selector
    all_elements = []
    _collect_html_elements(root, all_elements)
    context = [n for n in all_elements if _match_simple_selector(n, first_sel)]

    # Apply subsequent combinators
    for i in range(1, len(tokens)):
        combinator, sel = tokens[i]
        if not sel:
            continue

        if combinator == ">":
            # Direct child
            new_context = []
            for node in context:
                new_context.extend(c for c in node.children
                                   if not c.is_comment and not c.is_doctype
                                   and _match_simple_selector(c, sel))
            context = new_context
        else:
            # Descendant
            new_context = []
            for node in context:
                descs = []
                _collect_html_elements(node, descs)
                new_context.extend(d for d in descs if _match_simple_selector(d, sel))
            context = new_context

    return context


def query_css_and_output(content, opts, out):
    """Query HTML with CSS and output results"""
    root = parse_html(content)
    nodes = query_css(root, opts.query)

    indent_str = "\t" if opts.tab else " " * opts.indent
    color = opts.color and not opts.no_color

    for node in nodes:
        if opts.node:
            write_html_node(out, node, 0, indent_str, color)
        elif opts.attr:
