    print("  -q, --query string     Extract the node(s) using CSS selector")
    print("      --tab              Use tabs for indentation")
    print("  -v, --version          Print version information")
    print("  -x, --xpath string     Extract the node(s) from XML")


def main():
    opts = parse_args()

    if opts.version:
        print(f"xq version {VERSION}")
        return

    if opts.help:
        print_help()
        return

    if opts.files:
        filename = opts.files[0]
        try:
            with open(filename, 'r', encoding='utf-8', errors='replace') as f:
                content = f.read()
        except IOError as e:
            sys.stderr.write(f"Error: {e}\n")
            sys.exit(1)
    else:
        content = sys.stdin.read()

    import io
    if opts.in_place and opts.files:
        out_buf = io.StringIO()
        out = out_buf
    else:
