    opts.attr = ""
    opts.html = False
    opts.json = False
    opts.node = False
    opts.in_place = False
    opts.compact = False
    opts.depth = -1
    opts.files = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-v", "--version"):
            opts.version = True
        elif arg in ("-h", "--help"):
            opts.help = True
        elif arg == "--indent":
            i += 1
            opts.indent = int(args[i])
        elif arg in ("-c", "--color"):
            opts.color = True
        elif arg == "--no-color":
            opts.no_color = True
        elif arg == "--tab":
            opts.tab = True
        elif arg in ("-x", "--xpath"):
            i += 1
            opts.xpath = args[i]
        elif arg in ("-e", "--extract"):
            i += 1
            opts.extract = args[i]
        elif arg in ("-q", "--query"):
            i += 1
            opts.query = args[i]
        elif arg in ("-a", "--attr"):
            i += 1
            opts.attr = args[i]
        elif arg in ("-m", "--html"):
            opts.html = True
        elif arg in ("-j", "--json"):
            opts.json = True
        elif arg in ("-n", "--node"):
            opts.node = True
        elif arg in ("-i", "--in-place"):
            opts.in_place = True
        elif arg == "--compact":
            opts.compact = True
        elif arg in ("-d", "--depth"):
            i += 1
            opts.depth = int(args[i])
        elif not arg.startswith("-"):
            opts.files.append(arg)
        i += 1

    return opts


def print_help():
    print("Command-line XML and HTML beautifier and content extractor")
    print()
    print("Usage:")
    print("  xq [flags]")
    print()
