    print("      --indent int       Use the given number of spaces for indentation (default 2)")
    print("  -j, --json             Output the result as JSON")
    print("      --no-color         Disable colorful output")
    print("  -n, --node             Return the node content instead of text")
    print("  -q, --query string     Extract the node(s) using CSS selector")
    print("      --tab              Use tabs for indentation")
    print("  -v, --version          Print version information")
    print("  -x, --xpath string     Extract the node(s) from XML")


def main():
